#!/usr/bin/env bash
# Releases a new theme version: sets the version everywhere, commits, tags and pushes.
# The tag push starts .github/workflows/release.yml, which builds and publishes ars-petal.zip.
#
# Usage: npm run release 0.5.1              (or: bash bin/release.sh v0.5.1)
#        npm run release 0.5.1 -- --no-push   (commit and tag locally only)
#
# Files updated: style.css, readme.txt (Stable tag + a changelog entry), app/Theme.php,
# package.json, package-lock.json and the translation headers (regenerated by npm run i18n).
set -euo pipefail

cd "$(dirname "$0")/.."

push=1
version=""

for arg in "$@"; do
  case "$arg" in
    --no-push) push=0 ;;
    -*) echo "Unknown option: $arg" >&2; exit 1 ;;
    *) version="${arg#v}" ;;
  esac
done

fail() { echo "release: $*" >&2; exit 1; }

[[ -n "$version" ]] || fail "give a version, e.g. npm run release 0.5.1"
[[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail "version must look like 1.2.3, got $version"

tag="v$version"
current="$(sed -n 's/^Version:[[:space:]]*//p' style.css | tr -d '[:space:]')"

[[ "$version" != "$current" ]] || fail "style.css is already at $version"
# sort -V puts the higher version last.
[[ "$(printf '%s\n%s\n' "$current" "$version" | sort -V | tail -1)" == "$version" ]] || fail "$version is lower than the current $current"

[[ "$(git branch --show-current)" == "main" ]] || fail "switch to the main branch first"
# AGENTS.md is local notes (gitignored), so it doesn't count as a pending change.
if ! git diff --quiet -- . ':!AGENTS.md' || ! git diff --cached --quiet -- . ':!AGENTS.md'; then
  fail "commit or stash your changes first"
fi
git rev-parse -q --verify "refs/tags/$tag" > /dev/null && fail "tag $tag already exists"

if [[ $push -eq 1 ]]; then
  git fetch -q origin main --tags
  [[ -z "$(git rev-list HEAD..origin/main)" ]] || fail "main is behind origin/main, pull first"
  git ls-remote --exit-code --tags origin "refs/tags/$tag" > /dev/null && fail "tag $tag already exists on origin"
fi

command -v wp > /dev/null || fail "WP-CLI (wp) is needed to regenerate the translations"

echo "Releasing $current -> $version"

# Changelog entry: the commit subjects since the last version tag.
previous="$(git describe --tags --abbrev=0 --match 'v[0-9]*' 2> /dev/null || true)"
changes="$(git log --no-merges --format='* %s' ${previous:+"$previous"..HEAD} | grep -v '^\* Release v' || true)"
[[ -n "$changes" ]] || changes="* Maintenance release."

sed -i.bak "s/^Version:\([[:space:]]*\).*/Version:\1$version/" style.css
sed -i.bak "s/^Stable tag: .*/Stable tag: $version/" readme.txt
sed -i.bak "s/public const VERSION = '[^']*';/public const VERSION = '$version';/" app/Theme.php
sed -i.bak "s/\"Project-Id-Version: ARS Petal [^\\\\]*\\\\n\"/\"Project-Id-Version: ARS Petal $version\\\\n\"/" resources/lang/*.po
rm -f style.css.bak readme.txt.bak app/Theme.php.bak resources/lang/*.po.bak

# New changelog entry right under "== Changelog ==".
CHANGES="$changes" VERSION="$version" perl -0pi -e 's/(== Changelog ==\n\n)/$1= $ENV{VERSION} =\n$ENV{CHANGES}\n\n/' readme.txt

npm version "$version" --no-git-tag-version --allow-same-version > /dev/null
npm run --silent i18n > /dev/null

# Every place must now carry the new version.
grep -q "^Version:[[:space:]]*$version$" style.css || fail "style.css was not updated"
grep -q "^Stable tag: $version$" readme.txt || fail "readme.txt was not updated"
grep -q "VERSION = '$version'" app/Theme.php || fail "app/Theme.php was not updated"
grep -q "Project-Id-Version: ARS Petal $version" resources/lang/ars-petal.pot || fail "the .pot was not updated"

files=(style.css readme.txt app/Theme.php package.json package-lock.json resources/lang)
git add -- "${files[@]}"
git commit -q -m "Release $tag" -- "${files[@]}"
git tag -a "$tag" -m "$tag"
echo "Committed and tagged $tag"

if [[ $push -eq 1 ]]; then
  git push -q --atomic origin main "$tag"
  echo "Pushed main and $tag. GitHub Actions now builds and publishes ars-petal.zip."
else
  echo "Not pushed. When ready: git push --atomic origin main $tag"
fi
